// Word- and beat-level timing helpers shared by every scene.
// Data comes from src/data/timeline.ts, generated by scripts/*.mjs.

export type Mode = "dark" | "light";

export type Word = {
  text: string; // display text incl. punctuation, no surrounding spaces
  startMs: number;
  endMs: number;
  emphasis?: boolean; // [keyword] in script.json -> selection box
  pageBreakAfter?: boolean; // caption page ends after this word
  beat: number; // index into beats
};

export type Beat = {
  id: string;
  text: string; // plain narration for this beat
  scene: string; // key into SCENES
  mode: Mode;
  pose?: string; // presenter pose file name, "none" hides the presenter
  chapter?: string; // timeline node label (Format A)
  counter?: number; // counter value reached during this beat (Format A)
  counterLabel?: string;
  counterDanger?: boolean; // counter turns red
  hideTimeline?: boolean; // hide the chapter timeline during this beat
  startMs: number;
  endMs: number;
  firstWord: number;
  lastWord: number;
};

export type Segment = {
  scene: string;
  mode: Mode;
  startMs: number; // absolute
  endMs: number; // absolute, start of the next segment
  beats: Beat[];
  words: Word[];
};

export const msToFrame = (ms: number, fps: number) => Math.round((ms / 1000) * fps);

export const normalize = (s: string) => s.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, "");

// Index of the beat playing at `ms` (last beat whose start <= ms).
export const beatIndexAt = (beats: Beat[], ms: number) => {
  let idx = 0;
  for (let i = 0; i < beats.length; i++) {
    if (beats[i].startMs <= ms) idx = i;
    else break;
  }
  return idx;
};

// Consecutive beats with the same scene and mode become one <Sequence>, so a
// scene keeps animating across several caption pages.
export const groupSegments = (beats: Beat[], words: Word[], tailMs: number): Segment[] => {
  const segments: Segment[] = [];
  beats.forEach((beat) => {
    const last = segments[segments.length - 1];
    if (last && last.scene === beat.scene && last.mode === beat.mode) {
      last.beats.push(beat);
    } else {
      segments.push({ scene: beat.scene, mode: beat.mode, startMs: beat.startMs, endMs: 0, beats: [beat], words: [] });
    }
  });
  segments.forEach((seg, i) => {
    seg.startMs = i === 0 ? 0 : seg.startMs;
    const next = segments[i + 1];
    seg.endMs = next ? next.startMs : seg.beats[seg.beats.length - 1].endMs + tailMs;
    const first = seg.beats[0].firstWord;
    const lastWord = seg.beats[seg.beats.length - 1].lastWord;
    seg.words = words.slice(first, lastWord + 1);
  });
  return segments;
};

export type SceneProps = Segment;

// Clock for a scene: frame numbers are relative to the scene's <Sequence>.
//   const t = sceneClock(props, fps);
//   t.at("tables")        -> frame where the first "tables" in this scene starts
//   t.at("tables", 2)     -> second occurrence
//   t.end("tables")       -> frame where it ends
//   t.beat(1)             -> start frame of the scene's 2nd beat
//   t.ms(1200)            -> frame for an absolute ms timestamp
export const sceneClock = (scene: SceneProps, fps: number) => {
  const toLocal = (ms: number) => msToFrame(ms - scene.startMs, fps);
  const find = (word: string, occurrence: number) => {
    const target = normalize(word);
    let seen = 0;
    for (const w of scene.words) {
      if (normalize(w.text) === target) {
        seen++;
        if (seen === occurrence) return w;
      }
    }
    const available = scene.words.map((w) => w.text).join(" ");
    throw new Error(`sceneClock: "${word}" (#${occurrence}) not spoken in scene "${scene.scene}". Words: ${available}`);
  };
  return {
    at: (word: string, occurrence = 1) => toLocal(find(word, occurrence).startMs),
    end: (word: string, occurrence = 1) => toLocal(find(word, occurrence).endMs),
    beat: (i: number) => toLocal(scene.beats[Math.min(i, scene.beats.length - 1)].startMs),
    ms: toLocal,
    duration: toLocal(scene.endMs),
  };
};
